async function classifyTicketAsync(ticketId) {
  try {
    const ticket = await prisma.ticket.findFirst({
      where: { id: ticketId, deletedAt: null }
    });
    if (!ticket) {
      console.warn(`[TicketClassifier] Ticket '${ticketId}' not found for classification`);
      return null;
    }
    const classification = await classifyTicketContent(ticket.subject, ticket.description);
    const existingPayload = typeof ticket.rawPayload === "object" && ticket.rawPayload !== null ? ticket.rawPayload : {};
    await prisma.ticket.update({
      where: { id: ticketId },
      data: {
        priority: classification.priority,
        rawPayload: {
          ...existingPayload,
          aiClassification: {
            ...classification,
            classifiedAt: new Date().toISOString()
          }
        }
      }
    });
    return classification;
  } catch (error) {
    console.error(`[TicketClassifier] Failed to classify ticket ${ticketId} in background:`, error);
    return null;
  }
}

