  const preferredProvider = process.env.AI_PROVIDER?.toLowerCase() || (hasGoogleKey ? "google" : "openai");
  if (!hasGoogleKey && !hasOpenAIKey) {
    return getDeterministicAutoResolution(subject, description, customerName);
  }
