    const kbContent = getKnowledgeBaseContent();
    const isGoogle = preferredProvider === "google" && hasGoogleKey;
    const modelName = isGoogle ? process.env.GEMINI_CLASSIFY_MODEL || "gemini-3.5-flash-lite" : process.env.OPENAI_POLISH_MODEL || "gpt-5-nano";
    const model = isGoogle ? google2(modelName) : openai(modelName);
