// src/index.ts
var app = import_express4.default();
var PORT = process.env.PORT || 5000;
var allowedOrigins = getTrustedOrigins2();
app.use((_req, res, next) => {
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("X-Frame-Options", "DENY");
  res.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");
  res.setHeader("Permissions-Policy", "camera=(), microphone=(), geolocation=()");
  if (false) {}
  next();
});
app.use(import_cors.default({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error(`Origin '${origin}' not allowed by CORS`));
    }
  },
  credentials: true
}));
app.all("/api/auth/*", toNodeHandler2(auth));
app.use(import_express4.default.json());
app.use(import_cookie_parser.default());
app.use("/api/users", usersRouter);
app.use("/api/webhooks", webhooksRouter);
app.use("/api/tickets", ticketsRouter);
app.get("/", (_req, res) => {
  res.json({
    message: "Ticket Helper API Server is running",
    status: "ok",
    docs: {
      health: "/api/health",
      auth: "/api/auth",
      users: "/api/users",
      tickets: "/api/tickets",
      webhooks: "/api/webhooks/inbound-email"
    },
    clientUrl: process.env.CLIENT_URL || "http://localhost:5173"
  });
});
app.get("/api/health", (_req, res) => {
  res.json({
    status: "ok",
    runtime: "bun",
    queue: getQueueStatus(),
    timestamp: new Date().toISOString()
  });
});
app.use((err, _req, res, _next) => {
  console.error("Unhandled error:", err);
  res.status(500).json({ error: "Internal Server Error", message: err.message });
});
var server = app.listen(PORT, async () => {
  console.log(`[Express + Bun Server] running on http://localhost:${PORT}`);
  try {
    await startQueue();
  } catch (err) {
    console.error("[Queue] Initialization error:", err);
  }
});
var handleShutdown = async (signal) => {
  console.log(`[Server] Received ${signal}, shutting down gracefully...`);
  await stopQueue();
  server.close(() => {
    console.log("[Server] HTTP listener closed.");
    process.exit(0);
  });
};
process.on("SIGINT", () => handleShutdown("SIGINT"));
process.on("SIGTERM", () => handleShutdown("SIGTERM"));
